void set_chinese_osd(int x ,int y ,char *buffer,int type){
    for(int l=0;l<2;l++){
        for(int j=0 ;j<32;j++){
            for(int i=0 ;i<4;i++){
                char c;
                if(type)
                    c=fontdata_deliver[128*l+4*j+i];
                else
                    c=fontdata_clean[128*l+4*j+i];
                for(int k=0;k<8;k++){
                    if(c&(0x80 >> k)){
                        buffer[((y+j)*640+x+l*32+i*8+k)*3]=0xff;
                        buffer[((y+j)*640+x+l*32+i*8+k)*3+1]=0x00;
                        buffer[((y+j)*640+x+l*32+i*8+k)*3+2]=0x00;
                    }
                }
            }
        }
    }
}

void set_char_osd(int x ,int y ,char *buffer,char num){
    for(int j=0 ;j<32;j++){
        for(int i=0 ;i<2;i++){
            char c=fontdata_ter16x32[64*num+2*j+i];
            for(int k=0;k<8;k++){
                if(c&(0x80 >> k)){
                    buffer[((y+j)*640+x+i*8+k)*3]=0xff;
                    buffer[((y+j)*640+x+i*8+k)*3+1]=0x00;
                    buffer[((y+j)*640+x+i*8+k)*3+2]=0x00;
                }
            }
        }
    }
}

void set_string_osd(int x ,int y,char *buffer,char *str){
    int size = strlen(str);
    for(int i=0;i<size;i++){
        set_char_osd(x+16*i,y,buffer,str[i]);
    }
}

int capture_rtmp_init(video_frame_t *video_frame,char *rtmp_url){
    VideoParam g_video_param;
    memset(&g_video_param, 0, sizeof(g_video_param));
    g_video_param.level = 52;
    g_video_param.width=video_frame->width;
    g_video_param.height=video_frame->height;
    g_video_param.bit_rate=1024;
    g_video_param.frame_rate_den=1;
    g_video_param.frame_rate_num = 7;
    g_video_param.profile=77;
    memcpy(g_video_param.codec, "H.264", strlen("H.264"));
    memcpy(g_video_param.format, "NV12", strlen("NV12"));

	rkmuxer_init(3, "flv", rtmp_url, &g_video_param, NULL);

    return 0;
}

