int get_cam_video(int ch,char *video_path){
    DIR *d;
    struct dirent *dir;
    char path[64];
    if(ch)
        //外摄像头
        sprintf(path,"%s","/sys/bus/usb/devices/1-1/1-1.4/1-1.4:1.0/video4linux");
    else{
        d=opendir("/sys/bus/usb/devices/1-1/1-1.3/1-1.3:1.0/video4linux");
        if(d){
            sprintf(path,"%s","/sys/bus/usb/devices/1-1/1-1.3/1-1.3:1.0/video4linux");
            closedir(d);
        }
        else
            //内摄像头
            sprintf(path,"%s","/sys/bus/usb/devices/1-1/1-1.2/1-1.2:1.0/video4linux");
    }

    d = opendir(path); // 请替换为你要列出的目录路径
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            int fd;
            struct v4l2_capability cap;
            struct v4l2_fmtdesc fmt_desc;
            char video_name[12];
            if (strcmp(dir->d_name, ".") == 0 || strcmp(dir->d_name, "..") == 0) {
                continue;
            }
            sprintf(video_name,"/dev/%s",dir->d_name);
            fd = open(video_name, O_RDWR);
            if (fd < 0) {
                perror("打开视频设备失败");
                break;
            }

            // 查询设备属性
            if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
                perror("查询设备属性失败");
                close(fd);
                break;
            }

            // 检查设备是否支持视频捕获
            if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
                printf("设备不支持视频捕获\n");
                close(fd);
                break;
            }

            // 清零格式描述结构体
            memset(&fmt_desc, 0, sizeof(fmt_desc));
            fmt_desc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    
            // 遍历所有支持的格式
            while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt_desc) == 0) {
                if (fmt_desc.pixelformat == V4L2_PIX_FMT_MJPEG) {
                    printf("capture device : %s\n",video_name);
                    strcpy(video_path,video_name);
                    close(fd);
                    closedir(d);
                    return 0;
                    break;
                }
                fmt_desc.index++;
            }
        }
        video_path=NULL;
        closedir(d);
    } else {
        perror("无法打开目录");
        video_path=NULL;
        return -2;
    }
    video_path=NULL;
    return -1;
}

int reset_usb(int bus_num,int dev_num){
    char filename[32];
    int fd;
    int rc;
    printf("bus:dev=%03d:%03d\n",bus_num,dev_num);
    sprintf(filename,"/dev/bus/usb/%03d/%03d",bus_num,dev_num);

    fd = open(filename, O_WRONLY);
    if (fd < 0) {
        perror("Error opening output file");
        return 1;
    }
 
    printf("Resetting USB device %s\n", filename);
    rc = ioctl(fd, USBDEVFS_RESET, 0);
    if (rc < 0) {
        perror("Error in ioctl");
        return 1;
    }
    printf("Reset successful\n");
    close(fd);
}

int reset_cam(int ch){
    char path[64];
    DIR *d;

    if(ch){
        sprintf(path,"%s","/sys/bus/usb/devices/1-1/1-1.4/");
    }else{
        d=opendir("/sys/bus/usb/devices/1-1/1-1.3/");
        if(d){
            sprintf(path,"%s","/sys/bus/usb/devices/1-1/1-1.3");
            closedir(d);
        }else{
            sprintf(path,"%s","/sys/bus/usb/devices/1-1/1-1.2/");
        }
    }

    FILE *file;
    char path_name[64];
    char buffer[10]; // 假设busnum不会超过10个字符
    int dev_num;
    int bus_num;
    
    sprintf(path_name,"%s/busnum",path);
    // 打开文件
    file = fopen(path_name, "r");
    if (file == NULL) {
        perror("无法打开文件");
        return EXIT_FAILURE; 
    }

    // 读取内容
    if (fgets(buffer, sizeof(buffer), file) != NULL) {
        // 输出读取的内容
        printf("busnum: %s", buffer);
    } else {
        perror("读取文件时出错");
        fclose(file);
        return EXIT_FAILURE;
    }
    bus_num = atoi(buffer);
    // 关闭文件
    fclose(file);


    sprintf(path_name,"%s/devnum",path);
    // 打开文件
    file = fopen(path_name, "r");
    if (file == NULL) {
        perror("无法打开文件");
        return EXIT_FAILURE; 
    }

    // 读取内容
    if (fgets(buffer, sizeof(buffer), file) != NULL) {
        // 输出读取的内容
        printf("devnum: %s", buffer);
    } else {
        perror("读取文件时出错");
        fclose(file);
        return EXIT_FAILURE;
    }
    dev_num = atoi(buffer);
    // 关闭文件
    fclose(file);

    printf("%03d,%03d\n",bus_num,dev_num);
    reset_usb(bus_num,dev_num);    
    
    return 0;
}

